    // awkward gaps. The nonlinear terms distinguish useful fit from merely
    // making a numerically small residual.
    let mut score = residual_ratio * residual_ratio * 31.0;
    score += residual_ratio.powi(4) * 9.0;

    if residual == 0.0 {
        score -= 20.0;
    } else if residual < next {
        let mismatch = (next - residual).min(residual).max(0.0);
        score += mismatch * 4.1;
        if residual <= next * 0.5 {
            score += (next - residual) * 1.35;
        }
    } else {
        score -= (next / capacity) * 8.5;
    }

    // A residual that can consume the imminent item is especially valuable.
