        let utility = if next <= residual {
            3.0
        } else if residual >= next * 0.55 {
            1.15
        } else {
            0.32
        };
        score += (14.0 - residual) * utility;
    }

    // Favor placing into already occupied bins, but preserve a modest route
    // to a new bin when all open residuals are poorly aligned.
    score += occupancy_before * occupancy_before * 8.0;

    if residual > 0.0 {
        let deadness = (1.0 - (residual / 15.0).min(1.0))
            * (1.0 - (residual / next.max(1.0)).min(1.0));
        score += deadness * deadness * 6.2 * (0.45 + 0.55 * progress);
    }

    // Penalize fragmentation caused by leaving a gap that is hard to consume.
    let waste_ratio = (residual / capacity).min(0.5);
    score += waste_ratio * waste_ratio * (3.0 + 5.0 * progress);

    let stream_end = progress * progress * (3.0 - 2.0 * progress);
    let pressure = (open_bins_count as f64).sqrt();
    score -= pressure * (1.35 + 1.75 * stream_end);
    score -= mean_residual.max(0.0) * (0.016 + 0.028 * stream_end);

    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 + 6.0 * stream_end;
    }

