        let r = residual / next.max(1.0);
        let awkward = if r > 1.0 {
            // residual larger than the next item: the slot waits for a bigger
            // item that may never arrive
            (r - 1.0).min(3.0) * 0.9
        } else {
            // residual smaller than the next item: the slot may be too tight
            (1.0 - r) * 1.6
        };
        score += awkward * (1.2 + 1.8 * progress);
    }

    // Concentration pressure: prefer consolidating load into fewer bins when
    // the mean residual is already high relative to capacity (dead space
    // spread out across many bins).
