        let q = (residual as f64 / next.max(1.0)).round();
        let deviation = (residual / next.max(1.0) - q).abs();
        score += deviation * (1.0 + 1.5 * progress);
    }

    score *= 0.89 + 0.11 * (1.0 - progress);
    score
}

