    let occupancy_before = (1.0 - bin_residual as f64 / capacity).clamp(0.0, 1.0);
    let post_ratio = (residual / current).min(1.0);
    let demand_ratio = (next / capacity).clamp(0.0, 1.0);

    // Smaller residuals are intrinsically easier to fill, while exact closure
    // receives an additional consolidation bonus.
    let mut score = residual_ratio * residual_ratio * 42.0;
    score += residual_ratio.powi(4) * 13.0;
    if residual == 0.0 {
        score -= 31.0;
    }

    // Compare the residual with both the current and imminent item. This
    // couples immediate placement quality with one-step lookahead rather than
    // treating small residual size and useful residual size as the same goal.
    let next_gap = (next - residual).abs();
    let normalized_next_gap = (next_gap / next).min(1.0);
    let next_alignment = 1.0 - normalized_next_gap;
    score -= next_alignment * (7.0 + 5.0 * progress);

    if residual < next {
        let unusable = (next - residual).min(residual).max(0.0);
        score += unusable * (3.4 + 1.2 * progress);
        if residual <= next * 0.5 {
            score += (next - residual) * 1.15;
        }
    } else {
        score -= demand_ratio * 10.5;
    }

    // Reward residuals that can consume a useful future item, but decay this
    // value when the residual is already large relative to the bin.
    if residual > 0.0 && residual < 18.0 {
        let capability = if next <= residual {
            1.0
        } else if residual >= next * 0.55 {
            0.62
        } else {
            0.18
        };
        let scarcity = 1.0 - (residual / 18.0);
        score -= capability * scarcity * (5.0 + 4.0 * progress);
    }

    // Occupied bins are preferred, with stronger consolidation near the end.
    score += occupancy_before * occupancy_before * 11.0;
    if !is_new_bin && occupancy_before > 0.58 {
        let consolidation = (occupancy_before - 0.58) / 0.42;
        score -= consolidation * (4.0 + 5.0 * progress);
    }

    // A new bin is useful only when existing spaces are materially worse.
    // The threshold tightens when many alternatives exist and when the
    // stream has not yet supplied enough observations to predict demand.
    if is_new_bin {
        let opportunity = (fitting_bins_count as f64).min(8.0) / 8.0;
        score += 17.5 + 9.0 * opportunity + 7.0 * (1.0 - progress);
    } else if fitting_bins_count == 1 {
        score -= 15.0 + 7.0 * progress;
    }

    // Penalize dead space according to its absolute size and its spread over
    // many bins. Mean residual is particularly informative late in the run.
    if residual > 0.0 {
        let dead_fraction = (residual / 18.0).min(1.0);
        score += dead_fraction * dead_fraction * (4.0 + 5.0 * progress);
    }
    if !is_new_bin {
        let spread = (mean_residual.max(0.0) / capacity).min(1.0);
        if spread > 0.12 {
            score -= (spread - 0.12) * (8.0 + 8.0 * progress);
        }
    }

    // Prefer residuals close to the next demand, including a smooth nonlinear
    // preference for residuals just above it that can accept another copy.
    if !is_new_bin && residual > 0.0 {
        let ratio = residual / next;
        let target = if ratio <= 1.0 { ratio } else { 1.0 / ratio };
        score -= target * (5.0 + 5.5 * progress);

        let awkward = if residual < next {
            (1.0 - ratio).powi(2) * 3.2
        } else {
            ((ratio - 1.0) / (ratio + 1.0)) * 2.4
        };
        score += awkward * (1.5 + 2.0 * progress);

        // Near closure is valuable even when it does not exactly match the
        // next item; very large residuals receive less closure credit.
        let closure_scale = (current * 0.55).min(capacity * 0.18).max(1.0);
        if residual < closure_scale {
            let closure = 1.0 - residual / closure_scale;
            score -= closure * closure * (6.0 + 6.0 * progress);
        }
    }

