    // blindly favoring one bin when that bin would leave a poor gap.
    let bin_pressure = (open_bins_count as f64).sqrt();
    score -= bin_pressure * (1.25 + 1.5 * progress);
    score -= mean_residual.max(0.0) * (0.012 + 0.022 * progress);

