        let nearest = (residual / next).round();
        let deviation = (residual / next - nearest).abs();
        score += deviation * (2.0 + 2.5 * horizon);

        let narrow = 1.0 - (residual / 25.0).min(1.0);
        score += narrow * narrow * 5.5;

        let fill_gain = if residual >= next {
            (next / capacity) * (1.0 - residual_ratio)
        } else {
            0.0
        };
        score -= fill_gain * (10.0 + 7.0 * horizon);

