    let residual_ratio = (residual / capacity).clamp(0.0, 1.0);
    let occupancy_before = (1.0 - bin_residual as f64 / capacity).clamp(0.0, 1.0);

    // Residual space has sharply increasing cost as it becomes less reusable.
    // This cube-like response favors compact bins while preserving meaningful
    // gaps that can still accommodate upcoming items.
    let gap_cost = residual_ratio * residual_ratio * residual_ratio;
    let mut score = gap_cost * 44.0;

    if residual == 0.0 {
        score -= 19.0;
    } else if residual < next {
        let mismatch_ratio = ((next - residual) / next).clamp(0.0, 1.0);
        score += mismatch_ratio * mismatch_ratio * 15.0;
    } else {
        let next_fit = (next / residual).clamp(0.0, 1.0);
        score -= next_fit * next_fit * 10.0;
    }

