    if residual > 0.0 && residual < 16.0 {
        let reuse = (next / residual).clamp(0.0, 1.0);
        let urgency = 0.45 + 0.55 * progress;
        score += (16.0 - residual) * (0.18 + 1.75 * reuse * reuse) * urgency;
    }

    // Concentrate items in already occupied bins, but progressively increase
    // this preference once enough observations exist to trust the estimate.
    let consolidation = occupancy_before * occupancy_before;
    score += consolidation * (7.0 + 3.0 * progress);

    // Penalize residuals that are simultaneously small and awkward relative to
    // the incoming and upcoming item sizes.
    if residual > 0.0 {
        let smallness = (1.0 - (residual / 16.0).min(1.0)).max(0.0);
        let next_incompatibility =
            1.0 - (residual / next).clamp(0.0, 1.0);
        let current_incompatibility =
            1.0 - (residual / current.max(1.0)).clamp(0.0, 1.0);
        let deadness = smallness
            * (0.65 * next_incompatibility + 0.35 * current_incompatibility);
        score += deadness * deadness * (7.0 + 4.0 * progress);
    }

    let stream_end = progress * progress * (3.0 - 2.0 * progress);
    let pressure = (open_bins_count as f64).sqrt();
    score -= pressure * (1.15 + 1.7 * stream_end);
    score -= mean_residual.max(0.0)
        * (0.012 + 0.028 * stream_end + 0.012 * residual_ratio);

