    // but the opportunity cost rises with stream progress and existing bins.
    if is_new_bin {
        let mismatch = ((next - residual).max(0.0) / next).clamp(0.0, 1.0);
        let fresh_cost = 18.0 + 4.0 * progress + 0.35 * pressure;
        score += fresh_cost - 9.0 * mismatch * (0.35 + 0.65 * progress);
    }

