            0.0
        };
        score -= consolidation * (2.5 + 3.5 * stream_end) * (0.45 + 0.55 * residual_fit);
    }

    // A mildly nonlinear pressure term responds to growing residual spread
    // without overwhelming local fit quality.
    let spread_proxy = (mean_residual / capacity).clamp(0.0, 1.0);
    score -= spread_proxy * spread_proxy * (1.5 + 2.0 * stream_end);

    score *= 0.86 + 0.14 * (1.0 - progress);
    score
}
